   306  src_peek_line(pgp_source_t *src, char *buf, size_t len, size_t *readres)
   307  {
   308      size_t scan_pos = 0;
   309      size_t inc = 64;
   310      len = len - 1;
   311
   312      do {
   313          size_t to_peek = scan_pos + inc;
   314          to_peek = to_peek > len ? len : to_peek;
   315          inc = inc * 2;
   316
   317          /* inefficient, each time we again read from the beginning */
   318          if (!src_peek(src, buf, to_peek, readres)) {
   319              return false;
   320          }
   321
   322          /* we continue scanning where we stopped previously */
   323          for (; scan_pos < *readres; scan_pos++) {
   324              if (buf[scan_pos] == '\n') {
   325                  if ((scan_pos > 0) && (buf[scan_pos - 1] == '\r')) {
   326                      scan_pos--;
   327                  }
   328                  buf[scan_pos] = '\0';
   329                  *readres = scan_pos;
   330                  return true;
   331              }
   332          }
   333          if (*readres < to_peek) {
   334              return false;
   335          }
   336      } while (scan_pos < len);
   337      return false;
   338  }
